INSERT INTO PA_MeasureCalc (PA_MeasureCalc_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,Name,Description,SelectClause,WhereClause,DateColumn,OrgColumn,KeyColumn,AD_Table_ID,EntityType,PA_MeasureCalc_UU)
VALUES (1000023,11,0,'Y',TO_TIMESTAMP('2026-11-03 22:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-03 22:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Health Green','CAPEX dashboard tile 8: active projects with PV>0 whose SPI and (when AC>0) CPI are both >= 0.9','SELECT COUNT(*) FROM C_Project p','WHERE p.IsActive=''Y'' AND p.Processed=''N'' AND (SELECT COALESCE(SUM(ph.PlannedAmt),0) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND TRUNC(ph.EndDate)<=TRUNC(SYSDATE))>0 AND (SELECT COALESCE(SUM(ph.PlannedAmt),0) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND ph.IsComplete=''Y'')>=0.9*(SELECT COALESCE(SUM(ph.PlannedAmt),0) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND TRUNC(ph.EndDate)<=TRUNC(SYSDATE)) AND (COALESCE(p.ProjectBalanceAmt,0)<=0 OR (SELECT COALESCE(SUM(ph.PlannedAmt),0) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND ph.IsComplete=''Y'')>=0.9*COALESCE(p.ProjectBalanceAmt,0))','p.Created','p.AD_Org_ID','p.C_Project_ID',(SELECT AD_Table_ID FROM AD_Table WHERE TableName='C_Project'),'U','5a0c3e1e-0b7d-4c1e-9f3a-cafe00040001')
