-- Nov 3, 2026 — CAPEX Schedule Average Delay (days)
INSERT INTO PA_MeasureCalc (PA_MeasureCalc_ID,AD_Client_ID,AD_Org_ID,IsActive,Created,CreatedBy,Updated,UpdatedBy,Name,Description,SelectClause,WhereClause,DateColumn,OrgColumn,KeyColumn,AD_Table_ID,EntityType,PA_MeasureCalc_UU)
VALUES (1000031,11,0,'Y',TO_TIMESTAMP('2026-11-03 22:00:00','YYYY-MM-DD HH24:MI:SS'),100,TO_TIMESTAMP('2026-11-03 22:00:00','YYYY-MM-DD HH24:MI:SS'),100,'CAPEX Schedule Average Delay (days)','CAPEX dashboard tile 11: mean over at-risk + delayed projects of the days since their latest-ending overdue incomplete phase','SELECT AVG(COALESCE((SELECT MAX(daysbetween(TRUNC(SYSDATE),ph.EndDate)) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND COALESCE(ph.IsComplete,''N'')<>''Y'' AND ph.EndDate IS NOT NULL AND TRUNC(ph.EndDate)<TRUNC(SYSDATE)),0)) FROM C_Project p','WHERE p.IsActive=''Y'' AND p.Processed=''N'' AND EXISTS (SELECT 1 FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND ph.StartDate IS NOT NULL AND ph.EndDate IS NOT NULL) AND (((SELECT COALESCE(SUM(ph.PlannedAmt),0) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND TRUNC(ph.EndDate)<=TRUNC(SYSDATE))>0 AND (SELECT COALESCE(SUM(ph.PlannedAmt),0) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND ph.IsComplete=''Y'')<0.9*(SELECT COALESCE(SUM(ph.PlannedAmt),0) FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND TRUNC(ph.EndDate)<=TRUNC(SYSDATE))) OR EXISTS (SELECT 1 FROM C_ProjectPhase ph WHERE ph.C_Project_ID=p.C_Project_ID AND COALESCE(ph.IsComplete,''N'')<>''Y'' AND ph.EndDate IS NOT NULL AND TRUNC(ph.EndDate)<TRUNC(SYSDATE)))','p.Created','p.AD_Org_ID','p.C_Project_ID',(SELECT AD_Table_ID FROM AD_Table WHERE TableName='C_Project'),'U','5a0c3e1e-0b7d-4c1e-9f3a-cafe00040009')
;
